TWComponent.script:
tw.local.results = new tw.object.listOf.NameValuePair();
if(tw.local.productList != null)
{
	for(var i=0;i<tw.local.productList.listLength;i++)
	{
		tw.local.results[i] = new tw.object.NameValuePair();
		tw.local.results[i].name = tw.local.productList[i].arabicName;
		tw.local.results[i].value = tw.local.productList[i].productCode;
	}
	
}

